pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 100 wei);
        vm.prank(alice);
        c.addToBalance{value: 5 wei}();
        vm.prank(alice);
        bool ok;
        try c.addToBalance{value: 10 wei}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
